def calculate_sumset_size(T):
    """Calculates the size of the set {t_i + t_j | t_i, t_j in T, i <= j}."""
    sums = set()
    N = len(T)
    for i in range(N):
        for j in range(i, N):
            sums.add(T[i] + T[j])
    return len(sums)

